  var NS = "http://www.w3.org/2000/svg";

  function color(icon) {
    return icon.color || "var(--" + (icon.tone === "accent" ? "accent" : icon.tone === "accent3" ? "accent-3" : "accent-2") + ")";
  }

  // <svg> de un icono para el HTML (currentColor = el color del icono)
  function svgFor(id) {
    var icon = ICONS[id];
    var svg = document.createElementNS(NS, "svg");
    svg.setAttribute("viewBox", "0 0 24 24");
    svg.setAttribute("class", "skill__icon skill__icon--" + icon.kind);
    svg.style.color = color(icon);
    var path = document.createElementNS(NS, "path");
    path.setAttribute("d", icon.d);
    svg.appendChild(path);
    if (icon.label) svg.setAttribute("data-brand", icon.label);
    return svg;
  }

  // Convierte el <li> de una habilidad en: iconos + nombre (+ etiquetas de las marcas citadas).
  // Los iconos y etiquetas son decorativos (aria-hidden): la lista sigue siendo texto puro.
  function decorate(li, key, index) {
    var ids = (LISTS[key] || [])[index];
    if (!ids) return;
    var name = document.createElement("span");
    name.className = "skill__name";
    name.textContent = li.textContent;
    li.textContent = "";

    var icons = document.createElement("span");
    icons.className = "skill__icons";
    icons.setAttribute("aria-hidden", "true");
    ids.forEach(function (id) { icons.appendChild(svgFor(id)); });

    li.appendChild(icons);
    li.appendChild(name);

    var brands = ids.filter(function (id) { return ICONS[id].label; });
    if (brands.length) {
      var tags = document.createElement("span");
      tags.className = "skill__tags";
      tags.setAttribute("aria-hidden", "true");
      brands.forEach(function (id) {
        var tag = document.createElement("span");
        tag.textContent = ICONS[id].label;
        tag.style.setProperty("--tag", ICONS[id].color);
        tags.appendChild(tag);
      });
      li.appendChild(tags);
    }
    li.setAttribute("data-icons", ids.join(" "));
  }

  // Colores (hex) de los tonos del tema, para dibujar en un <canvas> (ver skills-graph.js)
  function toneHex(tone, palette) {
    var c = palette[tone === "accent" ? "accent" : tone === "accent3" ? "accent3" : "accent2"];
    return "#" + c.getHexString();
  }

  // Dibuja los iconos de una habilidad, centrados en (cx, cy), en un cuadrado de "box" px
  function draw(ctx, ids, cx, cy, box, palette) {
    var n = ids.length;
    var each = n === 1 ? box : box * 0.68;
    var gap = n === 1 ? 0 : box * 0.06;
    var total = n * each + (n - 1) * gap;
    ids.forEach(function (id, i) {
      var icon = ICONS[id];
      var path = new Path2D(icon.d);
      ctx.save();
      ctx.translate(cx - total / 2 + i * (each + gap), cy - each / 2);
      ctx.scale(each / 24, each / 24);
      if (icon.kind === "fill") {
        ctx.fillStyle = icon.color;
        ctx.fill(path);
      } else {
        ctx.strokeStyle = toneHex(icon.tone, palette);
        ctx.lineWidth = 1.8;
        ctx.lineCap = "round";
        ctx.lineJoin = "round";
        ctx.stroke(path);
      }
      ctx.restore();
    });
  }

  return { ICONS: ICONS, LISTS: LISTS, decorate: decorate, svgFor: svgFor, draw: draw };
